import{c as t,Q as a,j as r,m as n}from"./chunks/framework.BqPkuuVc.js";const o="/assets/rego-competitors-card-reader.BO3TSTux.png",s="/assets/dashboard-add-competitor-card-reader.BNR8Aenw.png",p=JSON.parse('{"title":"Late entries and the registration desk","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/late-entries.md","filePath":"user/running-the-event/late-entries.md"}'),i={name:"user/running-the-event/late-entries.md"};function d(h,e,l,g,c,u){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="late-entries-and-the-registration-desk" tabindex="-1">Late entries and the registration desk <a class="header-anchor" href="#late-entries-and-the-registration-desk" aria-label="Permalink to &quot;Late entries and the registration desk&quot;">​</a></h1><p><strong>Audience:</strong> Registration desk volunteers and timing operators handling on-the-day entries and changes.</p><p>How to enter people on the day, set them up with a class, a card and a start, and handle the changes the desk is asked for: a different class, a different card, somebody not running after all.</p><h2 id="you-can-add-people-at-any-time" tabindex="-1">You can add people at any time <a class="header-anchor" href="#you-can-add-people-at-any-time" aria-label="Permalink to &quot;You can add people at any time&quot;">​</a></h2><p>Manager doesn&#39;t lock the entry list when the event starts. Someone entered at 11:00 is as much a competitor as someone imported a week ago: they appear on every screen straight away, their card download is matched to them, and they&#39;re in the results.</p><p>There are three ways in:</p><ul><li><strong>The registration desk</strong>, a screen of its own for the entry table (below). This is the usual way on the day.</li><li><strong>Competitors → Actions → Add</strong>, or the add button on the dashboard&#39;s <strong>Quick actions</strong> tile, at the operator&#39;s own console.</li><li><strong>A card download.</strong> A card nobody holds can be assigned to an existing competitor, or used to add a new one, from the <a href="./card-download#fast-fixes-right-after-a-download">Card downloads</a> page. At a <a href="./../event-setup/low-key-events">low-key event</a>, Manager can enter unknown cards for you.</li></ul><h2 id="the-registration-desk" tabindex="-1">The registration desk <a class="header-anchor" href="#the-registration-desk" aria-label="Permalink to &quot;The registration desk&quot;">​</a></h2><p>The registration desk is a cut-down Manager for the entry table: find someone, fix them, or add them, and see what&#39;s on hire. It runs in a browser on a laptop or tablet. Take its link from <strong>Settings → Server</strong> (the <strong>Registration</strong> link). On a laptop with a card reader, use the <strong>IP</strong> link; see <a href="./../reference/server-addresses">Reaching the server</a>. Several desks can run at once, alongside the operator&#39;s console.</p><p>The desk shows only events that haven&#39;t been finished. Pick the event, and you get two screens in the bottom bar: <strong>Competitors</strong>, and <strong>Hire items</strong> (see <a href="./hire-items#the-same-box-at-the-registration-desk">Hire items</a>).</p><p><img src="'+o+'" alt="The registration desk&#39;s Competitors screen on a tablet: a search box holding 4410 with a card-reader icon, the orange add button beside it, and a card per matching competitor with their status, Class, Card number and Notes"></p><h3 id="finding-someone" tabindex="-1">Finding someone <a class="header-anchor" href="#finding-someone" aria-label="Permalink to &quot;Finding someone&quot;">​</a></h3><p>Everything goes in the one search box: a name or part of one, a card number, a class, a club, a bib. The list stays empty until you type, then shows everyone who matches.</p><p>With a SportIdent reader plugged into the desk&#39;s laptop, <strong>putting a card on the reader types its number into the search box</strong>. That&#39;s the fastest way to find a runner: they hold out their card, and the desk reads the answer. Connect the reader from the icon in the top bar the first time; see <a href="./card-download">Card download</a> for readers and browsers.</p><p>Reading a card at the desk only reads its number. It doesn&#39;t download the card or record a result.</p><h3 id="fixing-someone-on-the-spot" tabindex="-1">Fixing someone on the spot <a class="header-anchor" href="#fixing-someone-on-the-spot" aria-label="Permalink to &quot;Fixing someone on the spot&quot;">​</a></h3><p>Each match is a card with the three things the desk changes most often, right on it:</p><ul><li><strong>Class</strong>: they entered the wrong one, or moved up.</li><li><strong>Card number</strong>: they&#39;re carrying a different card, or a hire card. With the caret in this box, a card put on the reader fills it in for <em>this</em> runner rather than searching.</li><li><strong>Notes</strong>: anything someone needs to know later, such as &quot;borrowed card, back Sunday&quot;. See <a href="./../event-setup/competitors-clubs-teams#notes">Notes</a>.</li></ul><p>Changing any of them shows <strong>Save</strong> and <strong>Revert</strong> at the foot of the card. Nothing is sent until you press <strong>Save</strong>, so a card number read out a digit at a time is one change, not seven.</p><p>The chip at the top right is their status: whether they&#39;ve started, are out on course, or are back with a result. A runner who already has a result can still change class, but Manager then scores their run again against the new class&#39;s course.</p><p>For anything else (their name, club, start time, IDs), tap their name. That opens the same <strong>Edit competitor</strong> dialog the operator uses, with the same rules. See <a href="./../event-setup/competitors-clubs-teams#editing-an-existing-competitor">Competitors, clubs and teams</a>.</p><h3 id="adding-someone" tabindex="-1">Adding someone <a class="header-anchor" href="#adding-someone" aria-label="Permalink to &quot;Adding someone&quot;">​</a></h3><p>Press the orange add button beside the search box. When a search finds nobody, the screen offers <strong>Enter as a new competitor</strong> too, with the name you searched for already filled in. A card the reader can&#39;t find in the event offers <strong>Add</strong>, with its number filled in.</p><p><strong>Lock</strong>, under the <strong>⋮</strong> menu, signs the desk out when Manager has a PIN (see <strong>Settings → Access protection</strong>). Use it before you leave the table unattended.</p><h2 id="adding-a-competitor" tabindex="-1">Adding a competitor <a class="header-anchor" href="#adding-a-competitor" aria-label="Permalink to &quot;Adding a competitor&quot;">​</a></h2><p>Whether it&#39;s opened from the desk or from <strong>Competitors → Actions → Add</strong>, it&#39;s the same <strong>Add competitor</strong> dialog:</p><p><img src="'+s+'" alt="The Add competitor dialog: first name, surname, class, club, card number with the reader icon beside it, external ID, IOF ID, birth year, sex, allocated start time, and the Keep adding switch"></p><h3 id="what-you-need-and-what-can-wait" tabindex="-1">What you need, and what can wait <a class="header-anchor" href="#what-you-need-and-what-can-wait" aria-label="Permalink to &quot;What you need, and what can wait&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>On the day</th></tr></thead><tbody><tr><td><strong>First name</strong> / <strong>Surname</strong></td><td>At least one. As you type, Manager suggests people from the <a href="./../reference/competitor-registry">Competitor Registry</a>; picking one fills in their club, card and IDs.</td></tr><tr><td><strong>Class</strong></td><td>Needed for a result: someone without a class can&#39;t be scored or ranked.</td></tr><tr><td><strong>Card number</strong></td><td>Can be left blank and filled in later, or by their first card download.</td></tr><tr><td><strong>Club</strong></td><td>Optional. <strong>No club</strong> is fine.</td></tr><tr><td><strong>Allocated start time</strong></td><td>Optional at an event with a start punch. See <a href="#giving-them-a-start-time">Giving them a start time</a>.</td></tr><tr><td><strong>External ID</strong>, <strong>IOF ID</strong>, <strong>Birth year</strong>, <strong>Sex</strong></td><td>Optional. Filled in by the registry when you pick a registered person.</td></tr></tbody></table><p><strong>Saving without a class asks first.</strong> You can choose a class right there, <strong>Add without a class</strong> anyway, or go back. Someone entered without a class is still on every list, and still has their card read; they just can&#39;t be placed until they have one.</p><h3 id="reading-the-card-number-off-the-card" tabindex="-1">Reading the card number off the card <a class="header-anchor" href="#reading-the-card-number-off-the-card" aria-label="Permalink to &quot;Reading the card number off the card&quot;">​</a></h3><p>With a reader connected, the <strong>Card number</strong> field listens for a card: put the runner&#39;s card on the reader and its number fills in. It isn&#39;t downloaded. The reader icon beside the field turns this off and on, for when the card isn&#39;t in front of you: an entry taken over the phone, or a hire card handed out later. Your choice holds while the screen stays open.</p><p><strong>A card can fill in the whole entry.</strong> If the registry knows whose card it is, presenting it fills in their name, club and IDs as though you had picked them from the name fields, leaving you only the class to choose. It won&#39;t do that when:</p><ul><li><strong>nobody in the registry has that card</strong>: only the number is filled in;</li><li><strong>two people in the registry have it</strong>: Manager won&#39;t guess which one, so only the number is filled in;</li><li><strong>you&#39;ve already typed a name</strong>: the runner in front of you is whoever you typed. The card in their hand may be borrowed, or a hire card that was someone else&#39;s last time. The number fills in, and the name stays yours.</li></ul><p>If the name was filled in from one card and you then present a different one, the first card&#39;s person is replaced, or cleared if the registry doesn&#39;t know the new card.</p><p>Typing the number does the same as reading it, so a desk without a reader can still fill an entry from the registry.</p><h3 id="entering-a-queue-keep-adding" tabindex="-1">Entering a queue: Keep adding <a class="header-anchor" href="#entering-a-queue-keep-adding" aria-label="Permalink to &quot;Entering a queue: Keep adding&quot;">​</a></h3><p>Switch on <strong>Keep adding</strong> before you save, and the form clears for the next person instead of closing, with &quot;Added <em>name</em>&quot; beside the switch. The <strong>class</strong> is kept, because a queue is often one class at a time. Everything that identifies a person, such as their name, card, club, IDs and start time, starts blank, so one runner&#39;s card never ends up on the next runner&#39;s entry.</p><h3 id="when-manager-thinks-they-re-already-entered" tabindex="-1">When Manager thinks they&#39;re already entered <a class="header-anchor" href="#when-manager-thinks-they-re-already-entered" aria-label="Permalink to &quot;When Manager thinks they&#39;re already entered&quot;">​</a></h3><p>If someone already in the event has the same name, or the same card number, saving shows <strong>Possible duplicate</strong> with the matches listed. If it&#39;s a different person, click <strong>Add anyway</strong>. If it&#39;s the same person, cancel and work on the existing entry instead. (When the dialog was opened from a card download, it also offers <strong>Assign download</strong>, to give that card to the existing competitor.)</p><p>Two people holding the same card number is allowed, and flagged <strong>Duplicate</strong> on the Competitors list. That&#39;s fine for two people sharing a card at different times, and a problem for two running at once. See <a href="./../event-setup/competitors-clubs-teams#card-numbers">Card numbers</a>.</p><h2 id="giving-them-a-card" tabindex="-1">Giving them a card <a class="header-anchor" href="#giving-them-a-card" aria-label="Permalink to &quot;Giving them a card&quot;">​</a></h2><p>Their own card goes in <strong>Card number</strong>. For a <strong>hire card</strong>, put the hire card&#39;s number in the same field: if it&#39;s in the hire pool (<strong>Settings → Hire card registry</strong>), Manager marks them as being on a hire card, so the download desk is reminded to collect it. Compasses, map boards and anything else you lend are ticked on the competitor&#39;s <strong>Hire items</strong> tab. See <a href="./hire-items">Hire items</a>.</p><h2 id="giving-them-a-start-time" tabindex="-1">Giving them a start time <a class="header-anchor" href="#giving-them-a-start-time" aria-label="Permalink to &quot;Giving them a start time&quot;">​</a></h2><p>A late entry needs a start time to have a race time. Choose whichever way your start works:</p><ul><li><strong>They punch a start unit.</strong> Leave <strong>Allocated start time</strong> empty. Their start punch, read from their card when it&#39;s downloaded, becomes their start time. See <a href="./../event-setup/start-times">Start times</a>.</li><li><strong>They&#39;re given a start time.</strong> Type it into <strong>Allocated start time</strong>, in their class&#39;s lane. To find a free one, look at the order screen of the start draw (<strong>Starts</strong>): a draw with <strong>Reserve a gap every N starters</strong> leaves empty slots for exactly this, and you can see where they are. See <a href="./../event-setup/start-draw#start-draw-settings">Drawing start times</a>. Manager doesn&#39;t pick a free slot for you.</li><li><strong>The class has a mass start.</strong> Nothing to do: they start with the class.</li></ul><p>You can change it later from <strong>Edit competitor → Start</strong>, and the order screen shows them once they have a time.</p><h2 id="when-someone-isn-t-running-after-all" tabindex="-1">When someone isn&#39;t running after all <a class="header-anchor" href="#when-someone-isn-t-running-after-all" aria-label="Permalink to &quot;When someone isn&#39;t running after all&quot;">​</a></h2><ul><li><strong>Entered, but not starting</strong>: set their status to <strong>DNS</strong> (<strong>Edit competitor → Result</strong>). They stay in the event and go into the results file as a non-starter, which is what Eventor and your federation expect. At the end of the day, <strong>Competitors → Actions → Set competitors DNS</strong> does everyone who never started in one go.</li><li><strong>Entered by mistake, or twice</strong>: delete the entry (<strong>Edit competitor → Details → Delete</strong>). Deleting is permanent, and only right for an entry that should never have existed. The deletion is recorded in the <a href="./../reference/audit-trail">audit trail</a>.</li></ul><h3 id="marked-dns-then-they-turn-up" tabindex="-1">Marked DNS, then they turn up <a class="header-anchor" href="#marked-dns-then-they-turn-up" aria-label="Permalink to &quot;Marked DNS, then they turn up&quot;">​</a></h3><p>A <strong>DNS</strong> you set is a ruling, and Manager keeps it through everything that happens later, including a card download. So if someone was marked DNS and runs after all, take the ruling back: open them, go to <strong>Result</strong>, and press <strong>Auto</strong> beside the status. Manager then works their status out from what it knows again, from their download if they&#39;ve already finished. Do it before or after they run; either works.</p><h2 id="what-everyone-else-sees" tabindex="-1">What everyone else sees <a class="header-anchor" href="#what-everyone-else-sees" aria-label="Permalink to &quot;What everyone else sees&quot;">​</a></h2><p>A late entry or a change at the desk reaches every screen within a second or so: the operator&#39;s console, other desks, the download desk, TV screens and the spectator site. Nobody has to refresh.</p><p>Every change made at the desk is recorded in the event&#39;s audit trail with the source <strong>Entry desk</strong> and the name of the computer it was made at. To see what the desk changed today, filter the Audit trail screen by <strong>Source: Entry desk</strong>. See <a href="./../reference/audit-trail">Audit trail</a>.</p><p>To carry today&#39;s new cards and class changes into the next event, use the <a href="./../after-the-event/changes-report">changes report</a>. It lists people <strong>Entered on the day</strong> too.</p><h2 id="common-problems" tabindex="-1">Common problems <a class="header-anchor" href="#common-problems" aria-label="Permalink to &quot;Common problems&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>What to do</th></tr></thead><tbody><tr><td>The card number is already someone else&#39;s</td><td>Manager flags it <strong>Duplicate</strong>. If the other person isn&#39;t running at the same time, it&#39;s fine. If they are, one of them needs a different card, or the download will land on the wrong person.</td></tr><tr><td>The same person is in the list twice</td><td>Delete the extra entry. If cards have been read against both, move the download to the right one first from <a href="./card-download">Card downloads</a>.</td></tr><tr><td>The card on the reader fills in the wrong person</td><td>The registry knows that card as someone else&#39;s: a borrowed or hire card. Type the right name; Manager won&#39;t overwrite a name you typed.</td></tr><tr><td>The desk can&#39;t see the event</td><td>It has been finished. The desk only offers events that are still being set up or are running.</td></tr><tr><td>A class is &quot;full&quot;</td><td>Manager has no entry limit per class. If you need one, it&#39;s your call at the desk.</td></tr><tr><td>Someone ran but their result says DNS</td><td>See <a href="#marked-dns-then-they-turn-up">Marked DNS, then they turn up</a>.</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../event-setup/competitors-clubs-teams">Competitors, clubs and teams</a></li><li><a href="./hire-items">Hire items</a></li><li><a href="./../event-setup/start-times">Start times</a></li><li><a href="./card-download">Card download</a></li><li><a href="./resolving-issues">Resolving issues on the day</a></li><li><a href="./../after-the-event/changes-report">Changes report</a></li></ul>',59)])])}const f=t(i,[["render",d]]);export{p as __pageData,f as default};
